# PATCH 1.0.16 (v2): ⚠ и .has-overdue показываем только тем, кто вправе видеть задачу.
# Приоритет: emp_filter → только он; иначе нет прав на чужих → только свои; иначе — все.
_can_see_others = bool(perms.get('block.calendar.other_employees'))
_my_emp_v = (u.get('employee_id') or '').strip()
_visible_emp_ids = None
if emp_filter:
    if (not _can_see_others) and emp_filter != _my_emp_v:
        _visible_emp_ids = set()
    else:
        _visible_emp_ids = {emp_filter}
elif not _can_see_others:
    _visible_emp_ids = {_my_emp_v} if _my_emp_v else set()
for t in data['tasks']:
    if not _is_overdue(t, today):
        continue
    if _visible_emp_ids is not None:
        _asg = set(t.get('assignees') or [])
        if not (_asg & _visible_emp_ids):
            continue
    dl = t.get('deadline', '')
    if dl in days:
        days[dl]['overdue_tasks'].append({
            'id': t['id'], 'name': t.get('name', ''), 'icon': t.get('icon', '📋'),
        })
